// Semantic timing only. Model IDs and physical ranges belong to the renderer.
const smooth=t=>t*t*(3-2*t);
const curve=(t,points)=>{for(let i=1;i<points.length;i++){const [end,value]=points[i],[start,previous]=points[i-1];if(t<=end)return previous+(value-previous)*smooth(Math.max(0,(t-start)/(end-start)));}return points.at(-1)[1];};

/**
 * One-shot ambient actions.
 *
 * Two kinds of channel are used:
 *
 *  - `curve` drives the procedural head/body/gaze layer. Amplitudes here are
 *    deliberately modest: this model clamps ParamAngle* to about +/-10 degrees,
 *    so pushing harder only distorts the body without reading as movement.
 *  - `switches` drives the rig's OWN pose parameters (抬手 / 生气 / 睡觉 …).
 *    Those live in cdi3 parameter group 4 and expect the Visual-Studio-style
 *    0..100 range, NOT 0..1: the shipped taishou.exp3.json sets Param23 to 1,
 *    which is one percent of the pose and looks like nothing at all. This is the
 *    main reason the character seemed to have no real actions.
 *
 * Times are fractions of the action's duration.
 */
