/**
 * Overall gain for scripted actions.
 *
 * The rig was probed for its real parameter ranges: ParamAngleX/Y/Z run from -30
 * to +30, not the +/-10 that was assumed when these curves were written. The
 * curves were peaking around 12-20 degrees, so more than a third of the available
 * rotation was never used and the gestures read as barely-there.
 */
const ACTION_GAIN = 2.1;
/**
 * Whole-sprite movement gets its own, much larger gain.
 *
 * The pet window is only ~228px wide, so the head occupies roughly 60px: even a
 * full 30-degree turn moves it about fifteen pixels. Moving the whole sprite
 * through the projection matrix is not subject to any model parameter range, so
 * it stays the one channel that is unmistakable at this size.
 */
const POSITION_GAIN = 3.2;

/**
 * Does this action drive the gaze itself?
 *
 * Such an action takes the eyes over completely, which cancels the cursor
 * following the user is actively watching. Knowing which ones do this lets the
 * idle timer avoid them while the pointer is in motion.
 */
export function scriptsGaze(name){
  const spec=ACTIONS[name];
  if(!spec)return false;
  const steps=spec.steps??[spec];
  return steps.some(step=>step.curve&&(step.curve.gazeX||step.curve.gazeY));
}
/** Every action the motion system knows about, for scheduling and validation. */
export function actionNames(){ return Object.keys(ACTIONS); }

